@staticmethod
def fetch_cache_key(request: HttpRequest) -> str:
    """Return a hashed cache key built from the request body and user."""
    m = hashlib.sha256()
    user = getattr(request, "user", None)
    user_id = user.pk if user and user.is_authenticated else "anonymous"
    m.update(f"{user_id}:".encode("utf-8"))
    m.update(request.body)

    return m.hexdigest()

